INSERT INTO releases (version, released_on, title, public_notes, tech_notes) VALUES (
  '2.80.0',
  '2026-09-02',
  'Настройка «Какие страницы мне видны»',
  E'Страницу, которой не пользуетесь, теперь можно убрать с глаз: Settings → «Какие страницы мне видны», снимите галочку — и страница исчезнет из меню и с плиток главной. Только у вас.\n\nЭто не запрет: данные остаются на месте, по прямой ссылке и из результатов поиска страница открывается как обычно. Вернуть всё разом — кнопка «Показать все (N скрыто)».\n\nСами «Настройки» спрятать нельзя: иначе не осталось бы пути обратно.',
  E'user_settings.hidden_pages (миграция 0109) + PUT /me/pages/hidden, список заменяется целиком; GET /me/pages/order отдаёт его рядом с usage и pinned. Отдельная колонка от menu_pinned_pages: разные смыслы в одной колонке — приглашение к ошибке.\n\nСкрытие сознательно НЕ доступ: page_access остаётся админским, роутер скрытые страницы не блокирует, глобальный поиск по ним ищет. «Настройки» нельзя спрятать ни с клиента, ни с сервера (hidablePages) — единственный путь обратно.\n\nФильтр скрытых стоит внутри sortPages() в shared/pageOrder.ts, а не у вызывающих: меню и главная зовут одну функцию, и забыть его в одном из двух мест нельзя. Копия массива там обязательна — filter её и делает, sort правит на месте.\n\n«Показать все» шлёт ОДИН запрос со списком целиком. По странице за раз получалась бы пачка параллельных запросов, каждый со своим полным списком, и ответ отставшего вернул бы в интерфейс промежуточное состояние — поэтому публичный setHiddenPages(list), а setPageHidden — обёртка над ним.'
);
